420	<body>
421	  <main>
422	    <button type="button" class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to activate, double-click or tap twice to change color" aria-pressed="false" aria-expanded="false" aria-describedby="hint-text">
423	      <svg viewBox="0 0 400 400" preserveAspectRatio="xMidYMid meet" aria-hidden="true" role="presentation">
424	        <circle cx="200" cy="200" r="200"/>
425	      </svg>
426	    </button>
427	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
428	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click or tap to activate</div>
429	    <div class="controls" role="group" aria-label="Circle controls">
430	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
431	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
432	    </div>
433	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>R</kbd> to reset</div>
434	  </main>
435	
436	  <script defer>
437	    (() => {
438	      const COLORS = [
439	        { class: 'default', name: 'Default White' },
440	        { class: 'color-mode-1', name: 'Pink' },
441	        { class: 'color-mode-2', name: 'Teal' },
442	        { class: 'color-mode-3', name: 'Mint' },
443	        { class: 'color-mode-4', name: 'Purple' },
444	        { class: 'color-mode-5', name: 'Orange' }
445	      ];
446	
447	      const CONFIG = {
448	        storageKey: 'circle-state',
449	        tapDelay: 300,
450	        colorShiftDuration: 500,
451	        saveDebounceDuration: 100,
452	        keyDebounce: 50,
453	        isTouch: 'ontouchstart' in window || navigator.maxTouchPoints > 0 || navigator.msMaxTouchPoints > 0
454	      };
455	
456	      const el = {
457	        circle: document.getElementById('decorative-circle'),
458	        hint: document.getElementById('hint-text'),
459	        modeIndicator: document.getElementById('mode-indicator'),
460	        cycleBtn: document.getElementById('cycle-btn'),
461	        resetBtn: document.getElementById('reset-btn')
462	      };
463	
464	      let state = { active: false, colorMode: 0 };
465	      let tapCount = 0;
466	      let tapTimeout = null;
467	      let animatingColorShift = false;
468	      let saveTimeout = null;
469	      let lastKeyTime = 0;
470	
471	      const getColorClass = (mode) => COLORS[mode % COLORS.length].class;
472	      const getColorName = (mode) => COLORS[mode % COLORS.length].name;
473	
474	      const storage = {
475	        save() {
476	          clearTimeout(saveTimeout);
477	          saveTimeout = setTimeout(() => {
478	            try {
479	              localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
480	            } catch (e) {
481	              if (e.name === 'QuotaExceededError') {
482	                console.warn('Storage quota exceeded');
483	              }
484	            }
485	          }, CONFIG.saveDebounceDuration);
486	        },
487	        load() {
488	          try {
489	            const saved = localStorage.getItem(CONFIG.storageKey);
490	            if (saved) {
491	              const parsed = JSON.parse(saved);
492	              if (parsed?.active !== undefined && parsed?.colorMode !== undefined) {
493	                state = parsed;
494	              }
495	            }
496	          } catch (e) {
497	            // Silent failure - use default state
498	          }
499	        }
500	      };
501	
502	      const updateClasses = () => {
503	        const colorClasses = COLORS.map(m => m.class);
504	        el.circle.classList.remove('active', ...colorClasses);
505	        el.circle.setAttribute('aria-pressed', state.active);
506	        el.circle.setAttribute('aria-expanded', state.colorMode > 0);
507	        if (state.active) el.circle.classList.add('active');
508	        if (state.colorMode > 0) el.circle.classList.add(getColorClass(state.colorMode));
509	      };
510	
511	      const updateUI = () => {
512	        const hint = CONFIG.isTouch
513	          ? (state.active ? 'Tap twice to cycle • Tap to deactivate' : 'Tap to activate • Tap twice to cycle')
514	          : (state.active ? 'Double-click to cycle • Click to deactivate' : 'Click to activate • Double-click to cycle');
515	        el.hint.textContent = hint;
516	
517	        const showMode = state.active && state.colorMode > 0;
518	        el.modeIndicator.classList.toggle('visible', showMode);
519	        if (showMode) {
520	          el.modeIndicator.textContent = `◆ ${getColorName(state.colorMode).toUpperCase()}`;
521	        }
522	      };
523	
524	      const applyState = () => {
525	        updateClasses();
526	        updateUI();
527	      };
528	
529	      const toggleActive = () => {
530	        state.active = !state.active;
531	        applyState();
532	        storage.save();
533	      };
534	
535	      const cycleColor = () => {
536	        if (animatingColorShift) return;
537	        animatingColorShift = true;
538	        state.colorMode = (state.colorMode + 1) % COLORS.length;
539	        state.active = true;
540	        el.circle.classList.add('color-shifting');
541	        setTimeout(() => {
542	          el.circle.classList.remove('color-shifting');
543	          animatingColorShift = false;
544	        }, CONFIG.colorShiftDuration);
545	        applyState();
546	        storage.save();
547	      };
548	
549	      const resetState = () => {
550	        state = { active: false, colorMode: 0 };
551	        applyState();
552	        storage.save();
553	      };
554	
555	      const handleTouchEnd = () => {
556	        tapCount++;
557	        clearTimeout(tapTimeout);
558	        if (tapCount === 1) {
559	          tapTimeout = setTimeout(() => {
560	            if (tapCount === 1) toggleActive();
561	            tapCount = 0;
562	          }, CONFIG.tapDelay);
563	        } else if (tapCount === 2) {
564	          cycleColor();
565	          tapCount = 0;
566	        }
567	      };
568	
569	      const keyHandlers = {
570	        ' ': toggleActive,
571	        'enter': toggleActive,
572	        'escape': resetState,
573	        'c': cycleColor,
574	        'r': resetState
575	      };
576	
577	      const handleKeyDown = (e) => {
578	        const handler = keyHandlers[e.key.toLowerCase()];
579	        if (handler) {
580	          const now = Date.now();
581	          if (now - lastKeyTime >= CONFIG.keyDebounce) {
582	            e.preventDefault();
583	            handler();
584	            lastKeyTime = now;
585	          }
586	        }
587	      };
588	
589	      const initListeners = () => {
590	        if (CONFIG.isTouch) {
591	          el.circle.addEventListener('touchend', handleTouchEnd, { passive: true });
592	          if (window.PointerEvent) {
593	            el.circle.addEventListener('pointerup', handleTouchEnd, { passive: true });
594	          }
595	        } else {
596	          el.circle.addEventListener('click', toggleActive, { passive: true });
597	          el.circle.addEventListener('dblclick', cycleColor, { passive: true });
598	        }
599	        el.circle.addEventListener('blur', () => {
600	          tapCount = 0;
601	          clearTimeout(tapTimeout);
602	        });
603	        document.addEventListener('keydown', handleKeyDown);
604	        el.cycleBtn.addEventListener('click', cycleColor, { passive: true });
605	        el.resetBtn.addEventListener('click', resetState, { passive: true });
606	      };
607	
608	      const initApp = () => {
609	        storage.load();
610	        applyState();
611	        initListeners();
612	        el.circle.focus();
613	      };
614	
615	      const ensureSave = () => {
616	        clearTimeout(saveTimeout);
617	        try {
618	          localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
619	        } catch (e) {
620	          // Silently fail on storage errors during page hide
621	        }
622	      };
623	
624	      if (document.readyState === 'loading') {
625	        document.addEventListener('DOMContentLoaded', initApp);
626	      } else {
627	        initApp();
628	      }
629	
630	      window.addEventListener('pagehide', ensureSave);
631	    })();
632	  </script>
